use wasm_bindgen::prelude::*;

// 1. استيراد دالة alert من بيئة الـ JavaScript الخارجية:
#[wasm_bindgen]
extern "C" {
    fn alert(s: &str);

    #[wasm_bindgen(js_namespace = console)]
    fn log(s: &str);
}

// 2. تصدير دالة Rust ليتم استدعاؤها من الـ JavaScript:
#[wasm_bindgen]
pub fn greet_user(name: &str) -> String {
    let message = format!("مرحباً بك يا {} من داخل WebAssembly المكتوب بـ Rust!", name);

    // استدعاء console.log في المتصفح:
    log(&format!("Wasm Processed Greeting for: {}", name));

    // استدعاء alert في المتصفح:
    alert(&message);

    message
}

#[wasm_bindgen]
pub fn calculate_fibonacci(n: u32) -> u64 {
    if n <= 1 {
        return n as u64;
    }
    let mut a = 0;
    let mut b = 1;
    for _ in 2..=n {
        let temp = a + b;
        a = b;
        b = temp;
    }
    b
}

